<?php namespace App\Services; use App\Models\DocumentSequence; use Illuminate\Support\Facades\DB; class DocumentNumberService { public function next(string $key,string $prefix):string{return DB::transaction(function()use($key,$prefix){$s=DocumentSequence::lockForUpdate()->firstOrCreate(['key'=>$key],['prefix'=>$prefix,'next_number'=>1]);$n=$s->next_number;$s->increment('next_number');return sprintf('%s-%s-%06d',$prefix,now()->format('Y'),$n);});}}